import re

from pydantic import BaseModel, Field, field_validator

SEMVER_RE = re.compile(r"^\d+\.\d+\.\d+$")


class ToolDefinition(BaseModel):
    name: str
    description: str
    parameters: dict  # JSON Schema object; no deep validation in v1
    integration: str | None = None  # IntegrationBase.name (e.g., "smartsheet"); falls back to tool name if None
    action: str | None = None       # action string for execute(); falls back to tool name if None


class DataPanelConfig(BaseModel):
    worksheet_name: str = Field(min_length=1)
    google_docs_url: str | None = None


class WorkflowConfigSchema(BaseModel):
    version: str
    workflow_id: str
    tools: list[ToolDefinition]
    agent_instructions: str
    data_panel: DataPanelConfig | None = None

    @field_validator("version")
    @classmethod
    def version_is_semver(cls, v: str) -> str:
        if not SEMVER_RE.match(v):
            raise ValueError("version must be semver format, e.g. '1.0.0'")
        return v

    @field_validator("workflow_id")
    @classmethod
    def workflow_id_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("workflow_id must not be blank")
        return v

    @field_validator("agent_instructions")
    @classmethod
    def instructions_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("agent_instructions must not be blank")
        return v

import asyncio
import logging

import httpx

from app.core.config import settings
from app.core.exceptions import IntegrationError
from app.integrations.base import IntegrationBase, IntegrationStatus

logger = logging.getLogger(__name__)

_BASE_URL = "https://api.smartsheet.com/2.0"


class SmartsheetIntegration(IntegrationBase):
    def __init__(self) -> None:
        self._column_cache: dict[str, int] | None = None
        self._cache_lock = asyncio.Lock()

    @property
    def name(self) -> str:
        return "smartsheet"

    def _auth_header(self) -> dict[str, str]:
        return {"Authorization": f"Bearer {settings.SMARTSHEET_API_TOKEN}"}

    async def health_check(self) -> IntegrationStatus:
        if not settings.SMARTSHEET_API_TOKEN:
            return IntegrationStatus(
                name=self.name, status="unavailable", error="SMARTSHEET_API_TOKEN not set"
            )
        if not settings.SMARTSHEET_SHEET_ID:
            return IntegrationStatus(
                name=self.name, status="unavailable", error="SMARTSHEET_SHEET_ID not set"
            )
        try:
            async with httpx.AsyncClient(timeout=10.0) as client:
                response = await client.get(
                    f"{_BASE_URL}/sheets/{settings.SMARTSHEET_SHEET_ID}",
                    headers=self._auth_header(),
                )
            if response.status_code == 200:
                return IntegrationStatus(name=self.name, status="healthy")
            return IntegrationStatus(
                name=self.name,
                status="unavailable",
                error=f"Smartsheet API returned {response.status_code}",
            )
        except httpx.HTTPError as exc:
            return IntegrationStatus(
                name=self.name, status="unavailable", error=f"Smartsheet unreachable: {exc}"
            )

    async def _get_column_map(self) -> dict[str, int]:
        if self._column_cache is not None:
            return self._column_cache
        async with self._cache_lock:
            # Double-checked: another coroutine may have filled the cache while we waited.
            if self._column_cache is not None:
                return self._column_cache
            async with httpx.AsyncClient(timeout=10.0) as client:
                response = await client.get(
                    f"{_BASE_URL}/sheets/{settings.SMARTSHEET_SHEET_ID}/columns",
                    headers=self._auth_header(),
                )
            if response.status_code != 200:
                raise IntegrationError(
                    self.name, f"Could not fetch sheet columns: HTTP {response.status_code}"
                )
            try:
                data = response.json()
            except ValueError as exc:
                raise IntegrationError(
                    self.name, f"Smartsheet returned invalid JSON for columns: {exc}"
                ) from exc
            cache: dict[str, int] = {}
            for col in data.get("data", []):
                key = col["title"].lower().replace(" ", "_")
                if key in cache:
                    logger.warning(
                        "smartsheet_column_key_collision",
                        extra={"key": key, "sheet_id": settings.SMARTSHEET_SHEET_ID},
                    )
                cache[key] = col["id"]
            self._column_cache = cache
        return self._column_cache

    async def execute(self, action: str, params: dict) -> dict:
        if action != "submit_planning_request":
            raise IntegrationError(self.name, f"Unknown action: {action}")
        if not settings.SMARTSHEET_API_TOKEN or not settings.SMARTSHEET_SHEET_ID:
            raise IntegrationError(self.name, "Smartsheet is not configured")

        try:
            column_map = await self._get_column_map()
            cells = []
            for key, value in params.items():
                col_id = column_map.get(key)
                if col_id is None:
                    logger.warning(
                        "smartsheet_unmapped_param",
                        extra={"param": key, "sheet_id": settings.SMARTSHEET_SHEET_ID},
                    )
                    continue
                cells.append({"columnId": col_id, "value": value})

            if not cells:
                raise IntegrationError(
                    self.name, "No params matched any Smartsheet column — nothing to submit"
                )

            row_body = [{"toTop": True, "cells": cells}]
            async with httpx.AsyncClient(timeout=15.0) as client:
                response = await client.post(
                    f"{_BASE_URL}/sheets/{settings.SMARTSHEET_SHEET_ID}/rows",
                    headers={**self._auth_header(), "Content-Type": "application/json"},
                    json=row_body,
                )
            if response.status_code not in (200, 201):
                raise IntegrationError(
                    self.name,
                    f"Smartsheet rejected the planning request: HTTP {response.status_code}",
                )
            result = response.json()
            rows = result.get("result", {}).get("rows", [])
            row_id = rows[0].get("id", "unknown") if rows else "unknown"
            logger.info(
                "smartsheet_row_submitted",
                extra={"sheet_id": settings.SMARTSHEET_SHEET_ID, "row_id": row_id},
            )
            return {"row_id": row_id, "status": "submitted"}

        except IntegrationError:
            raise
        except httpx.HTTPError as exc:
            raise IntegrationError(
                self.name, f"Smartsheet request failed: {exc}"
            ) from exc

class IntegrationError(Exception):
    """Raised by IntegrationBase.execute() on integration failure."""
    def __init__(self, integration: str, message: str) -> None:
        self.integration = integration
        super().__init__(message)


class ProviderError(Exception):
    """Raised by LLMProvider.complete() or stream() on provider failure."""
    def __init__(self, provider: str, message: str) -> None:
        self.provider = provider
        super().__init__(message)


class MaskingError(Exception):
    """Raised by masking pipeline on PII processing failure."""

